"use strict";(self.webpackChunkgrc=self.webpackChunkgrc||[]).push([[37618],{67840:e=>{e.exports=JSON.parse('{"title":"Correct Is Not I/O Efficient: Characterizing I/O Behavior of LLM Agents on Scientific Data","authors":["I. Yildirim","J. Ye","J. Cernuda","X.-H. Sun","A. Kougkas"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","date":"May, 2026","month":5,"year":2026,"tags":["HPC","I/O Analysis","LLM Agents","Scientific Workflows","Storage Performance"],"links":{"bibtex":"http://cs.iit.edu/~scs/assets/files/yildirim2026correctisnotioefficient.bib","citation":"http://cs.iit.edu/~scs/assets/files/yildirim2026correctisnotioefficient.txt","poster":"http://cs.iit.edu/~scs/assets/files/yildirim2026correctisnotioefficient_poster.pdf"},"abstract":"LLM coding agents are increasingly used to generate scientific workflows, but evaluations stop at output correctness. For data-intensive science, this is incomplete: two workflows can produce the same valid result while placing different pressure on storage systems. We study I/O behavior in correctness-passing LLM-generated scientific workflows.\\nContributions: a benchmark of scientific data tasks paired with expert implementations and a containerized execution harness; POSIX-level tracing of agent-emitted code via DFTracer LD_PRELOAD inside isolated subprocesses; and per-step decomposition of I/O into the final solution path versus exploration overhead (failed attempts, inspection, verification, retries).\\nWe evaluate correctness-passing agent-generated workflows across several models and scientific tasks, then compare them with expert implementations. The results show that valid agent-generated scientific code can issue far more POSIX operations and read substantially more data than expert baselines, and that exploration overhead varies by model. The takeaway is that correctness alone is not a sufficient proxy for I/O efficiency, and storage behavior should be measured directly before deploying agent-generated workflows on shared HPC or cloud storage.","slug":"yildirim-2026-correct-is-not-io-efficient-9d2f"}')}}]);